CREATE TABLE IF NOT EXISTS org_positions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, code text UNIQUE NOT NULL, department_id uuid REFERENCES org_departments(id), level text NOT NULL, employment_track text NOT NULL DEFAULT 'Executive', jurisdiction text NOT NULL DEFAULT 'Continental', reports_to_position_id uuid REFERENCES org_positions(id), purpose text, key_responsibilities text, status text NOT NULL DEFAULT 'Planned', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());